// Кейс: .qa/tests/devices/DEV-009.md (шаг 2) · план: .qa/e2e-app/specs/app.md (1.33)
// «העתקת קישור» → буфер обмена (mobile: getClipboard) → ссылка https на домен Universal Link приложения. Ссылка НЕ открывается.
// Пропуск: при 2/2 (QR нет) или если буфер на реальном iPhone не читается (WDA не на переднем плане / нет доступа к буферу).
import { by, assert, skip } from '../../lib/appium.mjs';
import { openAddPhone, closeSheet } from './add-phone-sheet.test.mjs';

export const name = '«הוספת טלפון» → «העתקת קישור»: в буфере https://banci.expo.app/join… (Universal Link), ничего не открывается #e1b6f2 @iphone @app @prod-safe';

// Домен из AASA и комментария программиста 21.10 (applinks:banci.expo.app, paths /join, /join/*).
const APP_LINK_HOST = process.env.BANCI_APP_LINK_HOST || 'banci.expo.app';

export default async function (app) {
  const state = await openAddPhone(app);
  if (state === 'limit') {
    await closeSheet(app);
    skip('в аккаунте 2/2 телефона — QR и «העתקת קישור» не показываются (освободить слот вручную)');
  }

  // Очистить буфер, чтобы не принять старую ссылку за новую.
  await app.exec('mobile: setClipboard', { content: Buffer.from('').toString('base64'), contentType: 'plaintext' }).catch(() => {});
  await app.tap(by.exact('העתקת קישור'), { what: 'кнопка «העתקת קישור»' });

  // Опрос буфера до появления ссылки (без фиксированной паузы).
  let text = '';
  let lastErr;
  const end = Date.now() + 8000;
  while (Date.now() < end && !text) {
    try {
      const b64 = await app.exec('mobile: getClipboard', { contentType: 'plaintext' });
      text = Buffer.from(String(b64 || ''), 'base64').toString('utf8').trim();
    } catch (e) { lastErr = e; }
    if (!text) await new Promise((r) => setTimeout(r, 300)); // интервал опроса
  }
  await app.activate().catch(() => {}); // getClipboard на реальном iPhone может вывести WDA на передний план
  if (!text) {
    await app.restart();
    skip(`буфер обмена не прочитан${lastErr ? ` (${lastErr.message})` : ''} — проверить вручную вставкой в Заметки`);
  }
  console.log(`     ссылка: ${text.replace(/invite=[^&\s]+/, 'invite=…')}`);

  let url;
  try { url = new URL(text); } catch { assert(false, `в буфере ссылка, а не «${text.slice(0, 60)}»`); }
  assert(url.protocol === 'https:', `ссылка https (сейчас ${url.protocol})`);
  assert(url.hostname === APP_LINK_HOST, `домен Universal Link «${APP_LINK_HOST}» (сейчас «${url.hostname}»)`);
  assert(/^\/join(\/|$)/.test(url.pathname), `путь /join (покрыт AASA), сейчас «${url.pathname}»`);
  assert(url.searchParams.get('invite') || url.pathname.length > '/join/'.length, 'в ссылке есть код приглашения');

  // Приложение на месте, шторка открыта — закрыть.
  await app.waitFor(by.contains('חיבור טלפון נוסף'), { what: 'шторка «חיבור טלפון נוסף» после копирования' });
  await closeSheet(app);
  await app.restart();
}
